
from pathlib import Path
import csv
import matplotlib.pyplot as plt

# 1. Project directories
root = Path(__file__).resolve().parent.parent
sessions = root / "outputs" / "spark_sessions"
charts = root / "outputs" / "charts"

charts.mkdir(parents=True, exist_ok=True)

# 2. Read CSV files generated by Spark
def read_spark_csv(folder):
    files = list(folder.glob("part-*.csv"))

    if not files:
        raise FileNotFoundError(
            f"No Spark CSV found in: {folder}"
        )

    with open(files[0], newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


# 3. Traffic source distribution
traffic = read_spark_csv(
    sessions / "referrer_performance"
)

traffic.sort(
    key=lambda x: int(x["sessions"]),
    reverse=True
)

sources = [r["referrer"] for r in traffic]
counts = [int(r["sessions"]) for r in traffic]

plt.figure(figsize=(10, 5))
plt.bar(sources, counts)
plt.title("E-commerce Traffic Sources")
plt.xlabel("Traffic Source")
plt.ylabel("Number of Sessions")
plt.xticks(rotation=25)
plt.tight_layout()
plt.savefig(
    charts / "traffic_sources.png",
    dpi=200
)
plt.close()

print("Saved traffic_sources.png")


# 4. Session conversion percentages
conversion = read_spark_csv(
    sessions / "conversion_status"
)

labels = [r["conversion_status"] for r in conversion]
values = [int(r["sessions"]) for r in conversion]

plt.figure(figsize=(8, 6))
plt.pie(
    values,
    labels=labels,
    autopct="%1.1f%%",
    startangle=90
)
plt.title("Session Conversion Status (%)")
plt.tight_layout()
plt.savefig(
    charts / "conversion_percentage.png",
    dpi=200
)
plt.close()

print("Saved conversion_percentage.png")


# 5. Conversion rate by device
summary = read_spark_csv(
    sessions / "session_summary"
)

device_totals = {}
device_converted = {}

for row in summary:
    device = row["device_type"]
    status = row["conversion_status"]
    count = int(row["sessions"])

    device_totals[device] = (
        device_totals.get(device, 0) + count
    )

    if status == "converted":
        device_converted[device] = (
            device_converted.get(device, 0) + count
        )

devices = sorted(device_totals)

rates = [
    100 * device_converted.get(d, 0)
    / device_totals[d]
    for d in devices
]

plt.figure(figsize=(9, 5))
plt.bar(devices, rates)
plt.title("Session Conversion Rate by Device")
plt.xlabel("Device Type")
plt.ylabel("Conversion Rate (%)")
plt.ylim(0, max(rates) * 1.2)
plt.tight_layout()
plt.savefig(
    charts / "conversion_by_device.png",
    dpi=200
)
plt.close()

print("Saved conversion_by_device.png")

print("\nALL BEHAVIOR CHARTS COMPLETED")
print("Saved in:", charts)
